    [SkipLocalsInit]
    private static GpuBuffer<Vector2> _Misc_GPU(
        in GpuBuffers buffers,
        GpuBuffer<Vector2> position,
        GpuBuffer<Vector2> velocity,
        Vector2 max)
    {
        var device      = (WgpuDevice)buffers.GetDevice();
        // output ??= device.RentBuffer<Vector2>(buffers.count);  TODO
        using var task  = device.RentTask();

        // Dependencies from inputs (out not Output!)
        if (velocity.LastWritingTask != null) task.AddDependency(velocity);

        // Recording - task provides Encoder
        var encoder = task.GetEncoder("Misc"u8);
        using (var pass = encoder.BeginComputePass("Misc"u8))
        {
            var effect = device.GetEffect(_Misc_GPU_EffectSlot); // simple GpuEffect[] array lookup
            if (!effect.IsCreated) {
                effect = _Misc_GPU_CreateEffect(device);
            }
            pass.SetPipeline(effect.pipeline);
            
            // Creation of buffer bind group is expensive. Try get from cache with two entries.
            var bufferGroup = effect.bufferCache.GetGroup(buffers.hash);
            if (!bufferGroup.IsCreated) {
                Span<BindGroupEntry> entries = stackalloc BindGroupEntry[2];
                entries[0] = WgpuBindGroup.From(0, position);
                entries[1] = WgpuBindGroup.From(1, velocity);
                bufferGroup = task.CreateBindGroup(effect.bufferLayout, entries, "Misc_buffers"u8);
                device.UpdateBufferCache(_Misc_GPU_EffectSlot, bufferGroup, buffers.hash);
            }
            pass.SetBindGroup(0, bufferGroup);
            
            var uniforms = new _Misc_GPU_Uniforms {
                max = max,
                count = buffers.count,
            };
            var entry = task.AsUniformEntry(0, uniforms);
            // Creation of uniform bind group is cheap => no caching.
            var uniformGroup = task.CreateBindGroup(effect.uniformLayout, entry, "Misc_uniforms"u8);
            pass.SetBindGroup(1, uniformGroup);
            
            pass.DispatchWorkgroups((buffers.count + 63) / 64, 1, 1);
            pass.End();
        }
        // connect task to output
        ((WgpuBuffer<Vector2>)position).SetLastWritingTask(task);

        task.Finish(encoder, "Misc"u8);
        device.Enqueue(task); // queues CommandBuffer only. No Submit().

        // output.WaitInDebug();
        return null;
    }
    
