    [MethodImpl(MethodImplOptions.NoInlining)]
    private static WgpuEffect _Misc_GPU_CreateEffect(WgpuDevice device)
    {
        // @group(0)
        var bufferLayout = device.GetBindGroupLayout(_Misc_GPU_BufferLayoutKey);
        if (!bufferLayout.IsCreated) {
            Span<WgpuLayoutEntry> buffers = stackalloc WgpuLayoutEntry[2];
            buffers[0] = WgpuLayoutEntry.ReadWriteStorage<Vector2> (0); // var<storage, read_write>  position_arr: array<vec2<f32>>;
            buffers[1] = WgpuLayoutEntry.ReadOnlyStorage <Vector2> (1); // var<storage, read      >  velocity_arr: array<vec2<f32>>;
            bufferLayout = device.CreateBindGroupLayout(buffers, _Misc_GPU_BufferLayoutKey, "Misc_buffers"u8);
        }
        // @group(1)
        var uniformLayout = device.GetBindGroupLayout(_Misc_GPU_UniformLayoutKey);
        if (!uniformLayout.IsCreated) {
            Span<WgpuLayoutEntry> uniform = stackalloc WgpuLayoutEntry[1];
            uniform[0]    = WgpuLayoutEntry.Uniform<_Misc_GPU_Uniforms> (0); // var<uniform>              uniforms
            uniformLayout = device.CreateBindGroupLayout(uniform, _Misc_GPU_UniformLayoutKey, "Misc_uniforms"u8);
        }
        var shaderModule    = device.CreateShaderModule(_Misc_GPU_Shader(), "Misc"u8);
        var pipeline        = device.CreateComputePipeline(shaderModule, bufferLayout, uniformLayout, "Misc"u8);
        
        return device.CreateEffect(_Misc_GPU_EffectSlot, pipeline, bufferLayout, uniformLayout);
    }

    private static ReadOnlySpan<byte> _Misc_GPU_Shader() =>
    """
    struct Misc_Uniforms {
        max        : vec2<f32>,     // offset:  0 size:  8
        count      : u32,           // offset:  8 size:  4
    };                              //            size: 16
    
    @group(0) @binding(0) var<storage, read_write>  position_arr: array<vec2<f32>>;
    @group(0) @binding(1) var<storage, read      >  velocity_arr: array<vec2<f32>>;

    @group(1) @binding(0) var<uniform>              uniforms: Misc_Uniforms;

    @compute @workgroup_size(64)
    fn Misc(@builtin(global_invocation_id) global_id: vec3<u32>)
    {
        let index = global_id.x;
        if (index >= uniforms.count) {
            return;
        }
        var _position = position_arr[index];
        var _velocity = velocity_arr[index];
        var _max = uniforms.max;

        var _abs = abs(_velocity);
        var _trunc = trunc(_velocity);
        var _round = round(_velocity);
        var _min = min(_position, _velocity);
        var _max2 = max(_position, _velocity);
        var _clamp = clamp(_position, _velocity, _max);
        var _lerp = mix(_position, _velocity, _max);
        _position = ((((((_abs + _trunc) + _round) + _min) + _max2) + _clamp) + _lerp);

        position_arr[index] = _position;
    }
    """u8;

